    get(driveId: DriveId): Promise<Drive>
    archive(driveId: DriveId): Promise<Drive>
    unarchive(driveId: DriveId): Promise<Drive>
    /** Start deleting a drive (it becomes `deleting`). */
    delete(driveId: DriveId): Promise<Drive>
