    drives: {
      get: (driveId) => data('GET', `/drives/${driveId}`),
      archive: (driveId) => data('POST', `/drives/${driveId}/archive`),
      unarchive: (driveId) => data('POST', `/drives/${driveId}/unarchive`),
      delete: (driveId) => data('DELETE', `/drives/${driveId}`),
