      starred: (driveId, query) => page(`/drives/${driveId}/starred`, cursorQuery(query)),
      shared: (query) => page('/shared', cursorQuery(query)),
      get: (nodeId) => data('GET', `/nodes/${nodeId}`),
      getWithIncludes: (nodeId, include) =>
